import unittest
from candidate import common


class TestCommonFunction(unittest.TestCase):
    def test_common_basic_integers(self):
        self.assertEqual(common([1, 4, 3, 34, 653, 2, 5], [5, 7, 1, 5, 9, 653, 121]), [1, 5, 653])

    def test_common_simple_overlap(self):
        self.assertEqual(common([5, 3, 2, 8], [3, 2]), [2, 3])

    def test_common_empty_first_list(self):
        self.assertEqual(common([], [1, 2, 3]), [])

    def test_common_empty_second_list(self):
        self.assertEqual(common([1, 2, 3], []), [])

    def test_common_both_empty_lists(self):
        self.assertEqual(common([], []), [])

    def test_common_no_common_elements(self):
        self.assertEqual(common([1, 2, 3], [4, 5, 6]), [])

    def test_common_all_elements_same(self):
        self.assertEqual(common([1, 2, 3], [1, 2, 3]), [1, 2, 3])

    def test_common_single_element_match(self):
        self.assertEqual(common([1], [1]), [1])

    def test_common_single_element_no_match(self):
        self.assertEqual(common([1], [2]), [])

    def test_common_duplicates_in_first_list(self):
        self.assertEqual(common([1, 1, 1, 2, 2], [1, 2, 3]), [1, 2])

    def test_common_duplicates_in_second_list(self):
        self.assertEqual(common([1, 2, 3], [1, 1, 2, 2, 3, 3]), [1, 2, 3])

    def test_common_duplicates_in_both_lists(self):
        self.assertEqual(common([1, 1, 2, 2], [1, 1, 2, 2]), [1, 2])

    def test_common_negative_numbers(self):
        self.assertEqual(common([-5, -3, -1], [-1, -3, 0]), [-3, -1])

    def test_common_mixed_positive_negative(self):
        self.assertEqual(common([-2, 0, 2, 5], [0, 2, 7]), [0, 2])

    def test_common_with_zero(self):
        self.assertEqual(common([0, 1, 2], [0, 3, 4]), [0])

    def test_common_with_floats(self):
        self.assertEqual(common([1.5, 2.5, 3.5], [2.5, 3.5, 4.5]), [2.5, 3.5])

    def test_common_int_and_float_equal(self):
        self.assertEqual(common([1, 2, 3], [1.0, 2.0, 3.0]), [1.0, 2.0, 3.0])

    def test_common_with_strings(self):
        self.assertEqual(common(["a", "b", "c"], ["b", "c", "d"]), ["b", "c"])

    def test_common_with_tuples(self):
        self.assertEqual(common([(1, 2), (3, 4)], [(3, 4), (5, 6)]), [(3, 4)])

    def test_common_unsorted_returns_sorted(self):
        self.assertEqual(common([5, 3, 1, 4, 2], [4, 2, 5]), [2, 4, 5])

    def test_common_large_numbers(self):
        self.assertEqual(common([10**18, 10**18 + 1, 1], [1, 10**18 + 1, 10**18 + 2]), [1, 10**18, 10**18 + 1])

    def test_common_bool_values(self):
        self.assertEqual(common([True, False, 2], [True, False]), [False, True])

    def test_common_bool_and_int_equivalence(self):
        self.assertEqual(common([1, 0, 2], [True, False]), [False, True])

    def test_common_none_in_lists_no_match(self):
        self.assertEqual(common([None, 1, 2], [3, 4, 5]), [])

    def test_common_none_in_both_lists(self):
        result = common([None, 1], [None, 2])
        self.assertEqual(result, [None, 1])

    def test_common_none_and_number_no_match(self):
        self.assertEqual(common([None, 5], [3, 4]), [])

    def test_common_single_element_lists_match(self):
        self.assertEqual(common([42], [42]), [42])

    def test_common_single_element_lists_no_match(self):
        self.assertEqual(common([42], [43]), [])

    def test_common_returns_list_type(self):
        self.assertIsInstance(common([1, 2], [2, 3]), list)

    def test_common_returns_empty_list_type(self):
        self.assertIsInstance(common([], [1]), list)

    def test_common_with_repeated_single_common_element(self):
        self.assertEqual(common([1, 1, 1, 1], [1, 1]), [1])

    def test_common_three_element_overlap(self):
        self.assertEqual(common([1, 2, 3, 4, 5], [2, 3, 4, 6, 7]), [2, 3, 4])

    def test_common_with_negative_and_positive(self):
        self.assertEqual(common([-10, -5, 0, 5, 10], [-5, 0, 5]), [-5, 0, 5])

    def test_common_accepts_tuples_as_input(self):
        self.assertEqual(common((1, 2, 3), (2, 3, 4)), [2, 3])

    def test_common_accepts_range_as_input(self):
        self.assertEqual(common(range(5), range(3, 8)), [3, 4])

    def test_common_none_argument_first(self):
        with self.assertRaises(TypeError):
            common(None, [1, 2])

    def test_common_none_argument_second(self):
        with self.assertRaises(TypeError):
            common([1, 2], None)

    def test_common_both_none_arguments(self):
        with self.assertRaises(TypeError):
            common(None, None)

    def test_common_string_argument(self):
        self.assertEqual(common("abc", "bcd"), ['b', 'c'])

    def test_common_mixed_comparable_numbers(self):
        self.assertEqual(common([3, 1, 2], [1, 2, 3, 4]), [1, 2, 3])

    def test_common_float_precision(self):
        self.assertEqual(common([0.1, 0.2, 0.3], [0.2, 0.4, 0.5]), [0.2])

    def test_common_negative_floats(self):
        self.assertEqual(common([-1.5, -2.5, 0.5], [-2.5, 0.5, 1.5]), [-2.5, 0.5])

    def test_common_with_large_list(self):
        l1 = list(range(1000))
        l2 = list(range(500, 1500))
        expected = list(range(500, 1000))
        self.assertEqual(common(l1, l2), expected)

    def test_common_all_elements_unique_no_duplicates(self):
        self.assertEqual(common([1, 2, 3], [3, 2, 1]), [1, 2, 3])

    def test_common_only_one_common_element(self):
        self.assertEqual(common([1, 2, 3, 4, 5], [6, 7, 3, 8, 9]), [3])

    def test_common_with_zero_and_negative(self):
        self.assertEqual(common([0, -1, -2], [-2, -3, 0]), [-2, 0])

    def test_common_elements_not_in_order(self):
        self.assertEqual(common([9, 7, 5, 3, 1], [2, 4, 6, 8, 3, 5]), [3, 5])


if __name__ == '__main__':
    unittest.main()
